package guidancecontent

import (
	"github.com/jaxxstorm/fed/internal/readiness"
	"io/fs"
)

// SVC builds all 30 service-configuration variants, preserving Class B optionality.
func SVC(rules, markdown fs.FS) (readiness.Package, error) {
	return technicalDraft(rules, markdown, "SVC", "service-configuration", 30, []technicalRecipe{
		{code: "ACM", statement: "The configuration of machine-based information resources is managed using automation and persistently reviewed for drift.",
			purpose: "Verify automated configuration management and repeated review of deviations from intended and assessed state, including software, privileges, processes and availability where relevant.", capability: "configuration-state-and-history",
			scope:   "Machine-based resources and intended/assessed configurations across service accounts, clusters, namespaces and repositories; include unmanaged and ephemeral resource categories.",
			setup:   "Locate configuration authorities, automation controllers, intended/assessed baselines, current-state observations and drift-review records.",
			records: "Baseline and automation revisions, execution history, resource coverage reconciliation, current-versus-intended comparisons and dated drift-review conclusions.",
			review:  "Check actual automation use separately from drift review. Compare observed state to the intended and assessed state and retain findings; do not silently equate desired-state code with deployed state or execute corrective changes.", insufficient: "A configuration repository or occasional scan without automation execution and repeated drift review.",
			facets: []technicalFacet{{"managed using automation", "Automation manages machine-resource configuration.", "Automation definitions, execution records and resource coverage mapping.", "Manual change tickets with no automation."}, {"persistently reviewed for drift", "Repeated review identifies deviations from intended and assessed state.", "Versioned baseline comparisons, dates, findings and known review status.", "Comparisons against an unexplained baseline or no human/automated review conclusions."}}},
		{code: "ASM", statement: "Management, protection, and regular rotation of digital keys, certificates, and other secrets is automated and persistently reviewed.",
			purpose: "Assess automation and repeated review of secret management, protection and regular rotation for keys, certificates and other secrets; storing a secret in a vault is only part of the outcome.", capability: "secret-metadata-boundary",
			scope:   "Digital keys, certificates and other secrets used by the offering, including workload and third-party integration credentials; collect metadata and access history, not plaintext secret material.",
			setup:   "Locate secret/certificate/key metadata inventories, automation ownership, protection policies, documented rotation intervals and review history.",
			records: "Secret-type coverage map, automation policy revisions, access/protection observations, dated rotation results with old/new version metadata and repeated management/protection/rotation reviews.",
			review:  "Reconcile all secret categories to management, protection and rotation automation. Evaluate actual rotations against documented intervals, failures and review conclusions without retrieving secret values or triggering rotation.", insufficient: "A vault license, certificate expiry report or rotation policy without automated protection/rotation outcomes and repeated review.",
			timing: "Regular rotation follows a documented plan with consistent, predictable, repeated set intervals appropriate to each activity; no universal numeric rotation interval is specified. Retain scheduled and actual rotation dates separately from persistent review dates.",
			facets: []technicalFacet{{"Management, protection", "Secret management and protection are automated and reviewed.", "Lifecycle/protection automation versions, access enforcement observations and review conclusions for all secret categories.", "Rotation-only reports."}, {"regular rotation", "Rotation is automated, occurs at documented regular intervals and is persistently reviewed.", "Per-secret-class rotation plan, successful and failed run history, version transitions and dated review conclusions.", "An expiration date or planned rotation without execution."}}},
		{code: "EIS", statement: "Information resources are persistently evaluated for opportunities to improve security and those improvements are persistently made.",
			purpose: "Connect repeated security-improvement evaluation to improvements actually made, including managerial and personnel resources rather than only technical configuration.", capability: "configuration-state-and-history",
			scope:   "All relevant technical and non-machine information resources of the offering, including policies, procedures, people and supporting business processes.",
			setup:   "Locate security opportunity reviews, resource ownership, decision records and retained histories of completed improvements across technical and managerial resources.",
			records: "Dated opportunity evaluations, resource-to-opportunity mapping, decisions and evidence of implemented improvements linked to those evaluations, with known activity status.",
			review:  "Evaluate the recurring opportunity-identification process and recurring completed improvements separately. Trace claimed improvements to actual changed practices or resources; retain unresolved opportunities without executing remediation.", insufficient: "A backlog, roadmap or list of recommendations with no evidence improvements were actually made.",
			facets: []technicalFacet{{"persistently evaluated for opportunities to improve security", "Security-improvement opportunities are repeatedly evaluated.", "Dated resource evaluations with findings and rationale, including non-machine resources.", "Only vulnerability scan counts."}, {"those improvements are persistently made", "Evaluated improvements are repeatedly implemented.", "Versioned changes to systems, procedures or practices tied to evaluated opportunities and dates.", "Planned work or ticket status without resulting improvement evidence."}}},
		{code: "PRR", statement: "Plans, procedures, and the state of information resources are persistently reviewed after making changes to limit and remove unwanted residual elements that would likely negatively affect the confidentiality, integrity, or availability of federal customer data.",
			purpose: "Inspect repeated post-change review of plans, procedures and resource state for harmful residual elements, and records of limiting/removing those elements; avoid declaring every remnant harmful without contextual likelihood.", capability: "configuration-state-and-history",
			scope:   "Changed plans, procedures and machine/non-machine resource states, their residual elements and effects on federal agency customer data; preserve the defined customer-data boundary.",
			setup:   "Locate change histories, before/after plans and procedures, observed residual-state inventories and post-change risk reviews.",
			records: "Change identifiers and completion dates, post-change plan/procedure/state reviews, residual-element inventories, contextual likelihood and confidentiality/integrity/availability analysis, and records of limiting/removing relevant residuals.",
			review:  "Trace actual changes to subsequent reviews across all three subjects. Check how likely adverse effects on federal customer data were evaluated and what retained evidence shows residuals were limited or removed; assess records without changing resources.", insufficient: "A deployment-success log or generic cleanup checklist with no post-change state and customer-data risk review.",
			timing: "When changes have been made, review evidence must follow those changes and demonstrate persistent post-change review. This rule supplies no fixed elapsed-time deadline.",
			facets: []technicalFacet{{"Plans, procedures, and the state of information resources", "Post-change reviews examine plans, procedures and actual resource state.", "Versioned plans/procedures, observed states and linked post-change review conclusions.", "Only resource deletion logs with no plan/procedure review."}, {"limit and remove unwanted residual elements", "Reviews support limiting and removing harmful unwanted residuals.", "Residual inventory, contextual likelihood/risk rationale and attributable limiting/removal outcome records.", "A claim that all residual elements are harmless without analysis."}}},
		{code: "RUD", statement: "Unwanted federal customer data is removed promptly when requested by an agency in alignment with customer agreements, including from backups if appropriate; this typically applies when a customer spills information or when a customer seeks to remove information from a service due to a change in usage.",
			purpose: "Evaluate agency-requested removal of unwanted federal customer data against the agreement, promptness and backup appropriateness; spills and changed usage are typical examples, not exclusive triggers.", capability: "agency-data-removal-records",
			scope:   "Requesting agency's specified unwanted federal customer data, primary copies, replicas and backups as appropriate under customer agreements; distinguish provider-generated metadata from defined federal customer data.",
			setup:   "Locate agency request channels, customer agreement versions, data-location/backup maps and retained removal verification records. Establish request authority and requested scope without viewing unnecessary customer content.",
			records: "Agency request and receipt timestamp, applicable agreement clauses, data/copy scope, removal action and verification timestamps, backup inclusion or documented appropriateness rationale, and agency communication records.",
			review:  "Trace each request through data locations and agreement conditions to verified removal; assess unnecessary delay from the actual timeline and circumstances. Explain backup inclusion or exclusion. A supported no-request period is not proof of an executed removal; inspect existing evidence without deleting data.", insufficient: "A closed support ticket, primary-object deletion only, or blanket backup exclusion without agreement and appropriateness analysis.",
			timing: "When an agency requests removal, promptly means without unnecessary delay; preserve request, action and verification times, agreement commitments and reasons for elapsed time. No universal numeric deadline is supplied.",
			facets: []technicalFacet{{"removed promptly when requested by an agency in alignment with customer agreements", "Agency-requested removal follows applicable agreements without unnecessary delay.", "Request authority/scope, agreement version, receipt/removal/verification timeline and explanations for delay.", "A deletion policy without an actual request-linked outcome."}, {"including from backups if appropriate", "Backup removal is included where appropriate.", "Backup copy mapping, agreement/appropriateness decision and removal verification for included backup copies.", "Ignoring backups or assuming every backup must always be removed regardless of the condition."}}},
		{code: "SIN", statement: "Information is encrypted or otherwise secured from unwanted access or modification.",
			purpose: "Establish protection of information from both unwanted access and modification, allowing the source's encryption or otherwise-secured alternatives without declaring encryption alone sufficient.", capability: "information-protection-boundary",
			scope:   "Information in the offering's storage, processing and communication paths, including copies and administrative access paths; identify applicable protection mechanisms and responsibility boundaries.",
			setup:   "Locate information-flow/storage inventories, encryption and access/integrity protections, key-access relationships and observed protection evidence.",
			records: "Information-to-protection mapping, effective encryption/access/integrity configurations, authorization and validation observations, key-access boundaries and rationale/evidence for otherwise-secured paths.",
			review:  "Assess unwanted read access and unwanted modification separately for each information path. Explain how encryption or alternative protection addresses each outcome; do not infer encryption-at-rest secures all authorized-administrator modifications.", insufficient: "An encryption-enabled flag, transport-only scan or unsupported assertion that a private network secures every information path.",
			facets: []technicalFacet{{"unwanted access", "Information is protected from unwanted access.", "Effective read/access protections, encryption/key access mapping and observed authorization behavior.", "Integrity hashes without confidentiality/access protection."}, {"modification", "Information is protected from unwanted modification.", "Write authorization, integrity validation and effective modification-prevention evidence.", "Encryption-at-rest alone without write/integrity controls."}}},
		{code: "VCM", statement: "The authenticity and integrity of communications between machine-based information resources is persistently validated using automation.",
			purpose: "Demonstrate repeated automated validation of communication authenticity and integrity, not merely encryption settings or connectivity between machines.", capability: "information-protection-boundary",
			scope:   "Communication paths between machine resources, including internal, cross-service, cross-account and third-party machine interfaces within the service's responsibility.",
			setup:   "Locate machine communication maps, peer-authentication/trust and integrity-validation mechanisms, automation configuration and retained validation results.",
			records: "Path-to-validation coverage matrix, trust/identity configuration, integrity mechanism versions, automated validation runs or protocol verification observations and persistent activity history.",
			review:  "Check objective evidence of authentic peers/messages and communication integrity for each path class. Distinguish configured TLS from verified identity and integrity, including certificate/trust validation behavior and gaps.", insufficient: "An open port, connectivity test or TLS-enabled flag without automated authenticity/integrity validation outcomes.",
			facets: []technicalFacet{{"authenticity", "Automation repeatedly validates communication authenticity.", "Peer/message identity trust configuration and observed validation results with path coverage.", "Encryption with disabled identity verification."}, {"integrity", "Automation repeatedly validates communication integrity.", "Integrity-verification mechanism and observed validation results tied to communication paths.", "Authenticated peers without evidence of message/channel integrity validation."}}},
		{code: "VRI", statement: "Use cryptographic methods to validate the integrity of machine-based information resources.",
			purpose: "Show cryptographic integrity validation of actual machine resources against trustworthy references; computing or storing a hash alone is not validation.", capability: "information-protection-boundary",
			scope:   "Machine-based resources and relevant code, images, artifacts or configuration representations, with the covered resource types and trusted reference origins explicitly mapped.",
			setup:   "Locate integrity-validation mechanisms, signed artifacts or trustworthy reference digests, trust anchors, resource/version mapping and validation result history.",
			records: "Cryptographic method and verifier versions, trusted reference provenance, resource identifiers/revisions, verification runs/results and evidence that results concern deployed or used resources.",
			review:  "Trace cryptographic verification from a trustworthy reference to the specific resource version and objective integrity result. Explain coverage limitations; source repository signatures alone do not establish integrity of different deployed bytes.", insufficient: "An unsigned checksum with no trusted comparison, encryption settings, or signatures never verified against the actual resource."},
	})
}
